import{_ as t,a8 as a,o as i,c as n,ah as s,K as r}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"虚拟资料售卖：人设原则与平台机制","description":"","frontmatter":{"type":"preference","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["偏好","虚拟商品","知识产品","小红书","个人售卖","人设"]},"headers":[],"relativePath":"vault/Memory/Preferences/虚拟资料售卖人设与平台机制.md","filePath":"vault/Memory/Preferences/虚拟资料售卖人设与平台机制.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Preferences/虚拟资料售卖人设与平台机制.md"};function h(c,e,_,u,p,g){const l=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return i(),n("div",null,[e[0]||(e[0]=s('<h1 id="虚拟资料售卖-人设原则与平台机制" tabindex="-1">虚拟资料售卖：人设原则与平台机制 <a class="header-anchor" href="#虚拟资料售卖-人设原则与平台机制" aria-label="Permalink to “虚拟资料售卖：人设原则与平台机制”">​</a></h1><p>用户做「虚拟资料 / 知识产品」副业（WorkBuddy 手册 ¥9.9、AI 办公提示词模板包等）期间明确的跨项目偏好。</p><h2 id="一、人设原则-最稳打法" tabindex="-1">一、人设原则（最稳打法） <a class="header-anchor" href="#一、人设原则-最稳打法" aria-label="Permalink to “一、人设原则（最稳打法）”">​</a></h2><ul><li><strong>最稳人设 = 「整理过、验证过、愿意分享」的过来人</strong>，而非「刚好被安利的素人」。</li><li>卖家身份不能与人设矛盾：被发现是卖资料的人却用「朋友甩了个 X 给我」的素人视角写笔记，会掉信任。</li><li>顺商品用「被同事 / 朋友追着问」当背书，比「我顺便卖」自然——先有信任，再自然带出商品链接。</li><li>该原则由用户在一次笔记人设纠偏中确立（原稿写「朋友甩了个 WorkBuddy 给我」被否，改为「被同事追着问的整理者」）。</li></ul><h2 id="二、小红书-ai-类内容定位" tabindex="-1">二、小红书 AI 类内容定位 <a class="header-anchor" href="#二、小红书-ai-类内容定位" aria-label="Permalink to “二、小红书 AI 类内容定位”">​</a></h2><ul><li>做 <strong>How / 工具 / 效率</strong>，不做 <strong>资讯 / What-Why</strong>：资讯看完即走无收藏理由，CES 上不去。</li><li>起号期靠「高收藏干货清单 + 搜索长尾词 + 打工人身份 + 数字钩子」撬流量池。</li></ul><h2 id="三、小红书「个人售卖」平台机制-硬约束" tabindex="-1">三、小红书「个人售卖」平台机制（硬约束） <a class="header-anchor" href="#三、小红书「个人售卖」平台机制-硬约束" aria-label="Permalink to “三、小红书「个人售卖」平台机制（硬约束）”">​</a></h2><ul><li>开通：实名 + 注册满 30 天；入口「搞副业 → 创建商品」（勿点成「出闲置」）。</li><li>发货方式：无需邮寄 → 虚拟商品 → <strong>自动发货</strong>（拍下后平台私信自动发设置好的内容）。</li><li><strong>自动发货内容 ≤ 500 字</strong>；商品名 ≤ 20 字；手续费 0.6% / 笔。</li><li><strong>一篇笔记只能挂 1 个商品</strong>；个人售卖 <strong>不能投聚光、不能直播挂车</strong>（仅正规店铺可用）。</li><li>成交链路：飞书文档 URL 作商品交付物 → 笔记挂商品 → 买家拍下 → 平台私信自动发链接。</li></ul><h2 id="四、能力缺口-影响执行" tabindex="-1">四、能力缺口（影响执行） <a class="header-anchor" href="#四、能力缺口-影响执行" aria-label="Permalink to “四、能力缺口（影响执行）”">​</a></h2><ul><li><code>REDFOX_API_KEY</code> 未配置 → 红狐真实爆款数据与 <code>xiaohongshu-prohibited-word</code> 违禁词 API 检测均不可用；暂以 WebSearch + 人工合规自查替代。需要时在 redfox.hk 配 key。</li></ul><h2 id="如何应用" tabindex="-1">如何应用 <a class="header-anchor" href="#如何应用" aria-label="Permalink to “如何应用”">​</a></h2><ul><li>写任何「卖虚拟资料」的笔记 / 文案，先定人设（过来人），再写结构；严禁素人被安利视角。</li><li>规划小红书动作时，默认受「一篇 1 商品 / 不能投流」约束，只能靠笔记自然流量冷启动。</li></ul>',12)),r(l),r(o)])}const P=t(d,[["render",h]]);export{f as __pageData,P as default};
